{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS AS WITH CLEAN_AVAILABILITY AS ( SELECT CASE WHEN UPPER(TRIM(CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(CATEGORY)) END AS CATEGORY, CAST(PRICE AS NUMBER(10,2)) AS PRICE FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 WHERE CATEGORY IS NOT NULL AND PRICE IS NOT NULL AND PRICE > 0 ), CAT_BOUNDS AS ( SELECT CATEGORY, FLOOR(MIN(PRICE) / 200) * 200 AS START_PRICE, CEIL(MAX(PRICE) / 200) * 200 AS END_PRICE FROM CLEAN_AVAILABILITY GROUP BY CATEGORY ), SLAB_GENERATOR AS ( SELECT C.CATEGORY, SEQ.SEQ + 1 AS SLAB_NUMBER, CONCAT(\'SLAB_\', SEQ.SEQ + 1) AS PRICE_SLAB_CODE, (C.START_PRICE + (SEQ.SEQ * 200)) AS SLAB_MIN_PRICE, (C.START_PRICE + (SEQ.SEQ * 200) + 199) AS SLAB_MAX_PRICE FROM CAT_BOUNDS C JOIN ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS SEQ FROM TABLE(GENERATOR(ROWCOUNT => 100)) ) SEQ ON (C.START_PRICE + (SEQ.SEQ * 200)) < C.END_PRICE ) SELECT CATEGORY, PRICE_SLAB_CODE, SLAB_MIN_PRICE, SLAB_MAX_PRICE, CONCAT(\'₹\', SLAB_MIN_PRICE, \' – ₹\', SLAB_MAX_PRICE) AS PRICE_RANGE_LABEL, CURRENT_TIMESTAMP() AS UPDATED_AT FROM SLAB_GENERATOR ORDER BY CATEGORY, SLAB_MIN_PRICE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            